use semio_framework_test_fixtures::fixture_text;
use crate::*;
use crate::{DslValue,ValueRefusalKind,shared_issuance::SealedShared,retained_clone::{RetainedCloneBinding,RetainedCloneClose,RetainedCloneSource,retained_clone_grant_admits}};
use std::mem::{ManuallyDrop,size_of};
#[derive(crate::RetireOwned)]#[value(crate="crate")]struct Row{id:SealedShared<String>,name:SealedShared<String>,value:i64}
struct Receiving{binding:Option<RetainedCloneBinding>,fields:[NativeIntrinsicSharedField<String>;2],positions:[Option<usize>;2],id:ManuallyDrop<Option<SealedShared<String>>>,name:ManuallyDrop<Option<SealedShared<String>>>,output:ManuallyDrop<Option<Row>>,retirement:RetainedCloneClose,value:Option<i64>,index:usize,phase:u8,closing:bool,faulted:bool}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"native row requires exactly one id, name and integer value from its original source")}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}}
impl NativeReceive<DslValue> for Row{type Receiver=Receiving;fn receiver()->Receiving{Receiving{binding:None,fields:[NativeIntrinsicSharedField::default(),NativeIntrinsicSharedField::default()],positions:[None,None],id:ManuallyDrop::new(None),name:ManuallyDrop::new(None),output:ManuallyDrop::new(None),retirement:Default::default(),value:None,index:0,phase:0,closing:false,faulted:false}}}
impl Receiving{fn field<'a>(&self,original:RetainedCloneRef<'a,DslValue>,field:usize)->Result<RetainedCloneRef<'a,String>,ValueError>{let index=self.positions[field].ok_or_else(invalid)?;Ok(original.project(index,move|value|{let DslValue::Object(entries)=value else{unreachable!()};let DslValue::String(value)=&entries[index].1 else{unreachable!()};value}))}}
impl NativeReceiver<DslValue,Row> for Receiving{
 fn demands(&self,original:RetainedCloneRef<'_,DslValue>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase==7||self.phase==8||self.faulted{return Err(invalid())}original.check_binding(&self.binding)?;match self.phase{0=>Ok(fixed(original.binding_copy_bytes())),1=>Ok(fixed(0)),9=>Ok(fixed(size_of::<i64>())),2|3=>{let field=usize::from(self.phase-2);if self.fields[field].ready(){Ok(fixed(0))}else{self.fields[field].demands(self.field(original,field)?,body)}},4|5=>self.fields[usize::from(self.phase-4)].take_demand(),6=>Ok(fixed(0)),_=>Err(invalid())}}
 fn advance(&mut self,original:RetainedCloneRef<'_,DslValue>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,crate::OriginalReceivingPrimary>{let mut work=0;let mut own=false;let result=(||{let d=self.demands(original,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.checkpoint()?;match self.phase{
 0=>{if self.binding.is_none(){let turn=original.bind(&mut self.binding,g);work=turn.work;return turn.result.map(|p|RetainedCloneStep::Progress(p.unwrap_or_default())).map_err(Into::into)}work=1;own=true;self.phase=1;},
 1=>{work=1;own=true;let DslValue::Object(entries)=original.get()else{return Err(invalid().into())};if entries.len()!=3{return Err(invalid().into())}let(key,value)=entries.get(self.index).ok_or_else(invalid)?;match(key.as_str(),value){("id",DslValue::String(_))if self.positions[0].is_none()=>self.positions[0]=Some(self.index),("name",DslValue::String(_))if self.positions[1].is_none()=>self.positions[1]=Some(self.index),("value",DslValue::Number(value))if self.value.is_none()=>{value.as_i64().ok_or_else(invalid)?;self.phase=9;return Ok(RetainedCloneStep::Progress(receipt(d)))},_=>return Err(invalid().into())}self.index+=1;if self.index==3{self.phase=2;}},
 9=>{work=1;own=true;let DslValue::Object(entries)=original.get()else{return Err(invalid().into())};let(_,DslValue::Number(value))=entries.get(self.index).ok_or_else(invalid)?else{return Err(invalid().into())};self.value=Some(value.as_i64().ok_or_else(invalid)?);self.index+=1;self.phase=if self.index==3{2}else{1};},
 2|3=>{let field=usize::from(self.phase-2);if self.fields[field].ready(){work=1;own=true;self.phase+=1;}else{let input=self.field(original,field)?;let turn=self.fields[field].advance(input,control,body,g);work=turn.work;return turn.result.map(|p|RetainedCloneStep::Progress(p.progress())).map_err(Into::into)}},
 4|5=>{let field=usize::from(self.phase-4);let turn=self.fields[field].take(g);work=turn.work;let Some((value,p))=turn.result?else{return Ok(RetainedCloneStep::Progress(Default::default()))};if field==0{*self.id=Some(value)}else{*self.name=Some(value)}self.phase+=1;return Ok(RetainedCloneStep::Progress(p))},
 6=>{work=1;own=true;if self.id.is_none()||self.name.is_none()||self.value.is_none(){return Err(invalid().into())}*self.output=Some(Row{id:self.id.take().unwrap(),name:self.name.take().unwrap(),value:self.value.take().unwrap()});self.phase=7;},_=>return Err(invalid().into())}Ok(if self.phase==7{RetainedCloneStep::Complete(receipt(d))}else{RetainedCloneStep::Progress(receipt(d))})})();if result.is_err()&&own{self.faulted=true}let result=result.map_err(|mut error:crate::OriginalReceivingPrimary|{if own{let p=RetainedCloneProgress{copied_items:1,..Default::default()};error.progress=p;error.primary=error.primary.take().map(|value|value.with_retained_progress(p));}error});RetainedWorkOutcome{result,work}}
 fn output_ready(&self)->bool{!self.closing&&!self.faulted&&self.phase==7&&self.output.is_some()}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid())}Ok(fixed(0))}
 fn take(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome<Option<(Row,RetainedCloneProgress)>>{let mut work=0;let result=(||{let d=self.take_demand()?;if !retained_clone_grant_admits(g,d){return Ok(None)}work=1;self.phase=8;Ok(Some((self.output.take().ok_or_else(invalid)?,receipt(d))))})();RetainedWorkOutcome{result,work}}
 fn begin_close(&mut self){self.closing=true;for field in&mut self.fields{field.begin_close();}}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}for field in&self.fields{if !field.terminal_is_empty(){return field.close_demands(body)}}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<Row>(false,&None,body)}if self.output.is_some(){return self.retirement.next_owner_demands::<Row>(true,&None,body)}if self.id.is_some()||self.name.is_some(){return self.retirement.next_owner_demands::<SealedShared<String>>(true,&None,body)}if self.value.is_some()||self.faulted{return Ok(fixed(0))}RetainedCloneBinding::close_demand(&self.binding,body)}
 fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.closing{return Err(invalid())}for field in &self.fields{if !field.terminal_is_empty(){return field.close_work_demand(body)}}if !self.retirement.is_empty(){return self.retirement.next_owner_work::<Row>(false,&None,body)}if self.output.is_some(){return self.retirement.next_owner_work::<Row>(true,&None,body)}if self.id.is_some()||self.name.is_some(){return self.retirement.next_owner_work::<SealedShared<String>>(true,&None,body)}if self.value.is_some()||self.faulted{return Ok(1)}RetainedCloneBinding::close_work_demand(&self.binding,body)}
 fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementOutcome{let g=effect.grant();let mut work=0;let result:Result<RetainedCloneStep,crate::OriginalRetirementFailure>=(||{let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}for field in&mut self.fields{if !field.terminal_is_empty(){let turn=field.close_step(&mut effect.reborrow(g,effect.maximum_work_units()).expect("retirement child exceeds original effect"));work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}}if !self.retirement.is_empty(){let turn=self.retirement.step_granted(effect);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}macro_rules! close{($field:ident)=>{if self.$field.is_some(){let turn=self.retirement.begin_granted(&mut self.$field,effect);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.unwrap_or(RetainedCloneStep::Progress(Default::default())).progress())).map_err(Into::into)}}}close!(output);close!(id);close!(name);if self.value.is_some()||self.faulted{work=1;self.value=None;self.faulted=false;return Ok(RetainedCloneStep::Progress(receipt(d)))}let turn=RetainedCloneBinding::close_one(&mut self.binding,effect);work=turn.work;turn.result})();RetainedWorkOutcome{result,work}}
 fn terminal_is_empty(&self)->bool{!self.faulted&&self.value.is_none()&&self.fields.iter().all(NativeIntrinsicSharedField::terminal_is_empty)&&self.id.is_none()&&self.name.is_none()&&self.output.is_none()&&self.retirement.is_empty()&&self.binding.is_none()}
}
impl Drop for Receiving{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native receiving retains original physical owner");}}
pub(crate) struct Bank{left:RetainedCloneGrant,work:u64}
impl Bank{pub(crate) fn work_loan(&self,maximum:u64)->crate::source_fixture::WorkLoan<'_>{crate::source_fixture::WorkLoan::new(&self.work,maximum)}}
impl Bank{
 pub(crate) fn new()->Self{let f:serde_json::Value=serde_json::from_str(fixture_text!("../../🧪️tests/🧫️fixtures/📐️.json")).unwrap();let f=&f["stock"];Self{left:RetainedCloneGrant{maximum_items:f["items"].as_u64().unwrap()as usize,maximum_copy_bytes:f["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:f["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:f["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:f["depth"].as_u64().unwrap()as usize},work:f["fuel"].as_u64().unwrap()}}
 pub(crate) fn grant(&self)->RetainedCloneGrant{assert!(self.work>0&&self.left.maximum_items>0,"native field fixture exhausted its finite stock");RetainedCloneGrant{maximum_items:1,..self.left}}
 pub(crate) fn post(&mut self,p:RetainedCloneProgress,work:u64){assert!(p.fits(self.left));self.left.maximum_items=self.left.maximum_items.checked_sub(p.copied_items).unwrap();self.left.maximum_copy_bytes=self.left.maximum_copy_bytes.checked_sub(p.copied_bytes).unwrap();self.left.maximum_capacity_bytes=self.left.maximum_capacity_bytes.checked_sub(p.retained_capacity_bytes).unwrap();self.left.maximum_release_bytes=self.left.maximum_release_bytes.checked_sub(p.released_bytes).unwrap();self.work=self.work.checked_sub(work).unwrap();}
 pub(crate) fn step(&mut self,turn:RetainedWorkOutcome)->Result<RetainedCloneStep,ValueError>{let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());self.post(p,turn.work);turn.result}
 pub(crate) fn normal(&mut self,turn:RetainedWorkOutcome<RetainedCloneStep,crate::OriginalReceivingPrimary>)->Result<RetainedCloneStep,crate::OriginalReceivingPrimary>{let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());self.post(p,turn.work);turn.result}
}
fn advance(receiver:&mut Receiving,original:RetainedCloneRef<'_,DslValue>,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant,work_loan:crate::source_fixture::WorkLoan<'_>)->RetainedWorkOutcome<RetainedCloneStep,crate::OriginalReceivingPrimary>{crate::source_fixture::receive(control,g,work_loan,|control|receiver.advance(original,control,4096,g))}
pub(crate) fn drain<T:RetireOwned>(value:T,bank:&mut Bank){let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).unwrap_or_else(|_|panic!("native field fixture supports paid close"));for _ in 0..10000{if owner.terminal_is_empty(){return}let result=owner.step(bank.grant());let work=owner.last_turn_work();bank.step(RetainedWorkOutcome{result,work}).unwrap();}panic!("native field cleanup stalled")}
pub(crate) fn source(value:DslValue,bank:&mut Bank)->RetainedCloneSource<DslValue>{crate::source_fixture::capture(value,bank,Bank::grant,|bank,p,work,_,_|bank.post(p,work))}
fn input()->DslValue{let json:serde_json::Value=serde_json::from_str(fixture_text!("../../🧪️tests/🧫️fixtures/📐️.json")).unwrap();DslValue::Object(vec![("id".into(),DslValue::String(json["before"]["id"].as_str().unwrap().into())),("name".into(),DslValue::String(json["before"]["name"].as_str().unwrap().into())),("value".into(),DslValue::Number(crate::Number::Int(json["before"]["value"].as_i64().unwrap())))])}
fn close_receiver(receiver:&mut Receiving,bank:&mut Bank){receiver.begin_close();for _ in 0..10000{if receiver.terminal_is_empty(){return}let g=bank.grant();let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||receiver.close_step(g));let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.step(turn).unwrap();}panic!("refused native receiving did not close")}
fn take_row(receiver:&mut Receiving,bank:&mut Bank)->Row{let turn=receiver.take(bank.grant());let p=turn.result.as_ref().unwrap().as_ref().map(|(_,p)|*p).unwrap_or_default();bank.post(p,turn.work);turn.result.unwrap().unwrap().0}
fn denied(g:RetainedCloneGrant,d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut rows=vec![RetainedCloneGrant{maximum_items:0,..g}];if d.copy_bytes>0{rows.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g})}if d.capacity_bytes>0{rows.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g})}if d.release_bytes>0{rows.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g})}if d.depth>0{rows.push(RetainedCloneGrant{maximum_depth:d.depth-1,..g})}rows}
#[test]fn native_receive_original_row_has_funded_fields_and_every_cancellation_frontier(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../🧪️tests/🧫️fixtures/📐️.json")).unwrap();let mut observed=0;
 for cut in 0..128{let mut bank=Bank::new();let original=source(input(),&mut bank);let foreign=source(input(),&mut bank);let mut receiver=Row::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut turns=0;
  while turns<cut&&!receiver.output_ready(){let d=receiver.demands(original.borrow(),4096).unwrap();let g=bank.grant();if turns>0{assert!(receiver.demands(foreign.borrow(),4096).is_err())}for denied in denied(g,d){let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||advance(&mut receiver,original.borrow(),&mut control,denied,crate::source_fixture::WorkLoan::new(&bank.work,1)));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(receiver.demands(original.borrow(),4096).unwrap(),d);}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||advance(&mut receiver,original.borrow(),&mut control,g,crate::source_fixture::WorkLoan::new(&bank.work,1)));let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.normal(turn).unwrap();turns+=1;}
  if receiver.output_ready(){observed=turns;let row=take_row(&mut receiver,&mut bank);assert_eq!(row.id.as_str(),law["expected"]["id"].as_str().unwrap());assert_eq!(row.name.as_str(),law["expected"]["name"].as_str().unwrap());assert_eq!(row.value,law["expected"]["value"].as_i64().unwrap());assert_eq!(serde_json::json!({"id":row.id.as_str(),"name":row.name.as_str(),"value":row.value}),law["expected"]);drain(row,&mut bank);}close_receiver(&mut receiver,&mut bank);drain(original,&mut bank);drain(foreign,&mut bank);if observed>0&&cut>observed{break}
 }assert!(observed>0);
}
#[test]fn native_receive_constructor_and_output_denials_preserve_exact_owner(){
 let mut bank=Bank::new();let original=source(input(),&mut bank);let mut slot=tree::NativeReceiveSlot::<DslValue,Row>::default();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let original_pointer=original.borrow().get()as*const DslValue;let d=slot.demands(original.borrow(),4096).unwrap();assert!(d.capacity_bytes>0);let g=bank.grant();for denied in denied(g,d){let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||slot.advance(original.borrow(),&mut control,4096,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(slot.demands(original.borrow(),4096).unwrap(),d);assert_eq!(original.borrow().get()as*const DslValue,original_pointer);}slot.begin_close();assert!(slot.terminal_is_empty());
 let mut receiver=Row::receiver();for _ in 0..1000{if receiver.output_ready(){break}let turn=advance(&mut receiver,original.borrow(),&mut control,bank.grant(),crate::source_fixture::WorkLoan::new(&bank.work,1));bank.normal(turn).unwrap();}assert!(receiver.output_ready());let pointer=receiver.output.as_ref().unwrap().id.get().as_ptr();let d=receiver.take_demand().unwrap();let g=bank.grant();for denied in denied(g,d){let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||receiver.take(denied));assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!(heap,(0,0));assert!(receiver.output_ready());assert_eq!(receiver.output.as_ref().unwrap().id.get().as_ptr(),pointer);}let row=take_row(&mut receiver,&mut bank);assert_eq!(row.id.get().as_ptr(),pointer);drain(row,&mut bank);close_receiver(&mut receiver,&mut bank);drain(original,&mut bank);
}
#[test]fn native_receive_domain_and_original_callback_refusals_keep_all_partial_custody(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../🧪️tests/🧫️fixtures/📐️.json")).unwrap();let entries=law["refusedEntries"].as_array().unwrap().iter().map(|pair|(pair[0].as_str().unwrap().to_owned(),if let Some(value)=pair[1].as_str(){DslValue::String(value.to_owned())}else{DslValue::Number(crate::Number::Int(pair[1].as_i64().unwrap()))})).collect();let mut bank=Bank::new();let original=source(DslValue::Object(entries),&mut bank);let mut receiver=Row::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut refused=false;for _ in 0..16{let turn=advance(&mut receiver,original.borrow(),&mut control,bank.grant(),crate::source_fixture::WorkLoan::new(&bank.work,1));if bank.normal(turn).is_err(){refused=true;break}}assert!(refused);assert!(!receiver.output_ready());let DslValue::Object(entries)=original.borrow().get()else{panic!("original object changed")};assert_eq!(entries[0].0,entries[1].0);close_receiver(&mut receiver,&mut bank);drain(original,&mut bank);
 let original=source(input(),&mut bank);let mut receiver=Row::receiver();let admitted=std::cell::Cell::new(true);let mut callback=|_|admitted.get();let mut control=NativeDecodeControl::new(1<<20,&mut callback);for _ in 0..1000{if receiver.phase==3{break}let turn=advance(&mut receiver,original.borrow(),&mut control,bank.grant(),crate::source_fixture::WorkLoan::new(&bank.work,1));bank.normal(turn).unwrap();}assert_eq!(receiver.phase,3);assert!(receiver.fields[0].ready());admitted.set(false);let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||advance(&mut receiver,original.borrow(),&mut control,bank.grant(),crate::source_fixture::WorkLoan::new(&bank.work,1)));assert_eq!(turn.work,0);assert!(bank.normal(turn).is_err());assert_eq!(heap,(0,0));assert!(receiver.fields[0].ready());assert!(!receiver.output_ready());close_receiver(&mut receiver,&mut bank);drain(original,&mut bank);
}
#[test]fn fixed_array_native_default_repeats_the_scalar_default_only_under_its_own_grant(){
 let mut bank=Bank::new();let mut cursor=<[f64;3] as NativeDefault>::default_cursor();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let d=cursor.demands(4096).unwrap();let turn=cursor.advance(&mut control,4096,RetainedCloneGrant::default());assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(cursor.demands(4096).unwrap(),d);for _ in 0..10000{if cursor.output_ready(){break}let d=cursor.demands(4096).unwrap();let turn=cursor.advance(&mut control,4096,bank.grant());let p=turn.result.as_ref().unwrap().progress();assert_eq!(p.copied_bytes,d.copy_bytes);bank.normal(turn).unwrap();}assert!(cursor.output_ready());let turn=cursor.take(bank.grant());let p=turn.result.as_ref().unwrap().as_ref().map(|(_,p)|*p).unwrap_or_default();assert_eq!(p.copied_bytes,0);bank.post(p,turn.work);let(value,_)=turn.result.unwrap().unwrap();assert_eq!(value,[0.0;3]);drain(value,&mut bank);cursor.begin_close();for _ in 0..10000{if cursor.terminal_is_empty(){break}let turn=cursor.close_step(bank.grant());bank.step(turn).unwrap();}assert!(cursor.terminal_is_empty());let mut empty=<[u8;0] as NativeDefault>::default_cursor();let turn=empty.advance(&mut control,4096,bank.grant());assert!(bank.normal(turn).is_err());assert!(!empty.output_ready());empty.begin_close();assert!(empty.terminal_is_empty());
}
#[test]fn native_receive_slot_send_rests_on_the_receiver_contract(){fn is_send<T:Send>(){}fn is_static<T:'static>(){}fn receiver_contract<I:?Sized,T:NativeReceive<I>>(){is_send::<T::Receiver>();is_static::<T::Receiver>();is_send::<T>();}fn slot_is_send<I:super::tree::NativeValueSource+?Sized,T:NativeReceive<I>>(){is_send::<super::tree::NativeReceiveSlot<I,T>>();}let _=(receiver_contract::<DslValue,Row>,slot_is_send::<DslValue,Row>);}
#[test]fn native_receive_pure_row_header_allocates_no_backing(){let(receiver,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(Row::receiver);assert_eq!(heap,(0,0));let mut receiver=receiver;let mut bank=Bank::new();close_receiver(&mut receiver,&mut bank);}
